// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "T", "S"); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0));
        vm.assume(target != c.owner());
        vm.assume(amount > 0);
        uint256 balanceBefore = c.balanceOf(target);
        vm.prank(c.owner());
        c.mintToken(target, amount);
        uint256 balanceAfter = c.balanceOf(target);
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
